const PROVIDER_PRIORITY = ["notorganic", "openai-codex", "anthropic", "openai", "google"];

function sortProvidersByPriority(list: string[]): string[] {
	const rank = (name: string) => {
		const idx = PROVIDER_PRIORITY.indexOf(name);
		return idx === -1 ? PROVIDER_PRIORITY.length : idx;
	};
	return [...list].sort((a, b) => {
		const ra = rank(a);
		const rb = rank(b);
		if (ra !== rb) return ra - rb;
		return a.localeCompare(b);
	});
}

const stackClass = css({ display: "flex", flexDirection: "column", gap: "2rem" });
const dividerClass = css({ borderTop: "1px solid var(--border)" });

type ProviderEditorState = {
	dialog: ProviderDialogState;
	form: ProviderFormState;
	error: string;
	notice: string;
	saving: boolean;
};

type ProviderEditorAction =
	| { type: "open-add"; providerType: import("../lib/provider-models").KeatingCustomProviderType }
	| { type: "open-edit"; provider: KeatingCustomProvider; apiKey: string }
	| { type: "change"; form: ProviderFormState }
	| { type: "save-start" }
	| { type: "save-failed"; message: string }
	| { type: "save-finished"; notice: string }
	| { type: "close" };

const INITIAL_PROVIDER_EDITOR: ProviderEditorState = {
	dialog: { open: false },
	form: INITIAL_PROVIDER_FORM,
	error: "",
	notice: "",
	saving: false,
};

function providerEditorReducer(
	state: ProviderEditorState,
	action: ProviderEditorAction,
): ProviderEditorState {
	switch (action.type) {
		case "open-add":
			return {
				...INITIAL_PROVIDER_EDITOR,
				dialog: { open: true, type: action.providerType },
				form: {
					...INITIAL_PROVIDER_FORM,
					type: action.providerType,
					baseUrl: PROVIDER_TYPE_DEFAULTS[action.providerType] || "",
				},
				notice: state.notice,
			};
		case "open-edit":
			return {
				...INITIAL_PROVIDER_EDITOR,
				dialog: { open: true, provider: action.provider },
				form: {
					name: action.provider.name,
					type: action.provider.type,
					gatewayKind: action.provider.gatewayKind ?? "bifrost",
					baseUrl: action.provider.baseUrl,
					apiKey: action.apiKey || action.provider.apiKey || "",
				},
				notice: state.notice,
			};
		case "change":
			return { ...state, form: action.form, error: "" };
		case "save-start":
			return { ...state, saving: true, error: "" };
		case "save-failed":
			return { ...state, saving: false, error: action.message };
		case "save-finished":
			return { ...INITIAL_PROVIDER_EDITOR, notice: action.notice };
		case "close":
			return { ...INITIAL_PROVIDER_EDITOR, notice: state.notice };
	}
}

export function ProvidersModelsTab({ extraNavSections }: { extraNavSections?: SettingsSection[] } = {}) {
	const [customProviders, setCustomProviders] = useState<KeatingCustomProvider[]>([]);
	const [settings, patch] = useKeatingUiSettings();
	const [modelPrefs] = useModelPrefs();
	const [providerEditor, dispatchProviderEditor] = useReducer(
		providerEditorReducer,
		INITIAL_PROVIDER_EDITOR,
	);

	useEffect(() => {
		loadCustomProviders().then(setCustomProviders);
	}, []);

	const providers = sortProvidersByPriority(Array.from(new Set([
		...(isNotOrganicFeatureEnabled() ? [NOTORGANIC_PROVIDER_ID] : []),
		...getProviders(),
	])));

	const handleToggleProvider = (provider: string, hidden: boolean) => {
		toggleProviderVisibility(provider, hidden);
	};

	const handleAddModel = async (model: { name: string; id: string; provider: string; api: string; baseUrl: string; apiKey: string; reasoning: boolean; vision: boolean }) => {
		const key = `${model.provider}::${model.api}::${model.id}`;
		addCustomModel({
			key,
			id: model.id,
			name: model.name,
			provider: model.provider,
			api: model.api,
			baseUrl: model.baseUrl.trim() || undefined,
			reasoning: model.reasoning,
			vision: model.vision,
		});
		if (model.apiKey.trim()) {
			await getAppStorage().providerKeys.set(model.provider, model.apiKey.trim());
		}
	};

	const handleSaveProvider = async () => {
		const { dialog, form } = providerEditor;
		if (!form.name.trim() || !form.baseUrl.trim()) {
			dispatchProviderEditor({ type: "save-failed", message: "Name and Base URL are required" });
			return;
		}
		const isEdit = !!dialog.provider;
		dispatchProviderEditor({ type: "save-start" });
		try {
			const storage = getAppStorage();
			const providerId = dialog.provider?.id ?? crypto.randomUUID();
			let provider: KeatingCustomProvider = {
				id: providerId,
				name: form.name.trim(),
				type: form.type,
				gatewayKind: form.type === "gateway" ? form.gatewayKind : undefined,
				baseUrl: form.baseUrl.trim(),
				apiKey: form.apiKey.trim() || undefined,
				models: dialog.provider?.models ?? [],
			};
			let discoveryWarning = "";
			if (AUTO_DISCOVERY_TYPES.has(provider.type)) {
				try {
					const models = await discoverCustomProviderModels(provider);
					provider = { ...provider, models };
					if (models.length === 0) {
						discoveryWarning = " Saved, but no models were listed. Add the model manually below.";
					}
				} catch (error) {
					const message = error instanceof Error ? error.message : "model listing failed";
					discoveryWarning = ` Saved, but automatic model discovery failed (${message}). Add the model manually below.`;
				}
			}
			await storage.customProviders.set(provider as any);
			const oldName = dialog.provider?.name;
			if (oldName && oldName !== provider.name) {
				await storage.providerKeys.delete(oldName);
			}
			if (form.apiKey.trim()) {
				await storage.providerKeys.set(provider.name, form.apiKey.trim());
			} else {
				await storage.providerKeys.delete(provider.name);
			}
			await loadCustomProviders().then(setCustomProviders);
			dispatchProviderEditor({
				type: "save-finished",
				notice: `${provider.name} ${isEdit ? "updated" : "saved"}.${discoveryWarning}`,
			});
		} catch (error) {
			console.error("Failed to save provider:", error);
			const message = error instanceof Error ? error.message : "Unknown connection error";
			dispatchProviderEditor({
				type: "save-failed",
				message: `${isEdit ? "Failed to update" : "Failed to save"} provider: ${message}`,
			});
		}
	};

	const handleDeleteProvider = async (provider: KeatingCustomProvider) => {
		if (!confirm("Are you sure you want to delete this provider?")) return;
		try {
			const storage = getAppStorage();
			await storage.customProviders.delete(provider.id);
			await storage.providerKeys.delete(provider.name);
			await loadCustomProviders().then(setCustomProviders);
		} catch (error) {
			console.error("Failed to delete provider:", error);
		}
	};

	const openAddType = (type: import("../lib/provider-models").KeatingCustomProviderType) => {
		dispatchProviderEditor({ type: "open-add", providerType: type });
	};

	const openEdit = async (provider: KeatingCustomProvider) => {
		const apiKey = await getAppStorage().providerKeys.get(provider.name).catch(() => undefined);
		dispatchProviderEditor({ type: "open-edit", provider, apiKey: apiKey ?? "" });
	};

	return (
		<div className={settingsSection()}>
			<SettingsSectionNav
				sections={[
					{ id: "cloud-providers", label: "Cloud" },
					{ id: "web-search", label: "Web Search" },
					{ id: "provider-visibility", label: "Visibility" },
					{ id: "my-models", label: "My Models" },
					{ id: "custom-providers", label: "Custom Providers" },
					...(extraNavSections ?? []),
				]}
			/>

			<CloudProviderKeysSection providers={providers.filter((p) => !modelPrefs.hiddenProviders.includes(p))} />

			<div className={dividerClass} />

			<WebSearchSection settings={settings} onPatch={patch} />

			<div className={dividerClass} />

			<ProviderVisibilitySection
				providers={providers}
				modelPrefs={modelPrefs}
				onToggle={handleToggleProvider}
			/>

			<div className={dividerClass} />

			<MyModelsSection
				modelPrefs={modelPrefs}
				customProviders={customProviders}
				onAddModel={handleAddModel}
			/>

			<div className={dividerClass} />

			<CustomProvidersSection
				customProviders={customProviders}
				notice={providerEditor.notice}
				onEdit={openEdit}
				onDelete={handleDeleteProvider}
				onAddType={openAddType}
			/>

			<ProviderDialog
				dialog={providerEditor.dialog}
				form={providerEditor.form}
				error={providerEditor.error}
				saving={providerEditor.saving}
				onChange={(form) => dispatchProviderEditor({ type: "change", form })}
				onClose={() => dispatchProviderEditor({ type: "close" })}
				onSave={handleSaveProvider}
			/>
		</div>
	);
}

import { providerDefinition } from "./provider-config";
import type { ProviderId, ProviderSettings } from "./types";
import type { ReasoningLevel } from "./ui-settings";

export const MODELS_DEV_CATALOG_URL = "https://models.dev/api.json";
export const LONG_CONTEXT_THRESHOLD = 256_000;

export const MODEL_CAPABILITY_FILTERS = [
  { value: "thinking", label: "Thinking" },
  { value: "vision", label: "Vision" },
  { value: "long-context", label: "Long context" },
] as const;

export type ModelCapabilityFilter = (typeof MODEL_CAPABILITY_FILTERS)[number]["value"];

export type NativeModelTransport =
  | "openai-responses"
  | "anthropic-messages"
  | "google-generative-ai"
  | "openai-chat-completions";

export const NATIVE_PROVIDER_TRANSPORT: Readonly<Record<ProviderId, NativeModelTransport>> = {
  openai: "openai-responses",
  anthropic: "anthropic-messages",
  google: "google-generative-ai",
  openrouter: "openai-chat-completions",
  custom: "openai-chat-completions",
};

export interface CatalogModel {
  key: string;
  provider: ProviderId;
  providerLabel: string;
  id: string;
  name: string;
  description: string;
  reasoning: boolean;
  reasoningLevels: ReasoningLevel[];
  temperature: boolean;
  vision: boolean;
  contextWindow: number;
  maxOutputTokens: number;
  transport: NativeModelTransport;
  source: "models.dev" | "built-in" | "custom";
}

export interface CatalogSections {
  recent: CatalogModel[];
  cloud: CatalogModel[];
  custom: CatalogModel[];
}

type ModelsDevProviderId = Exclude<ProviderId, "custom">;

const MODELS_DEV_PROVIDERS = new Set<ModelsDevProviderId>(["openai", "anthropic", "google", "openrouter"]);
const PROVIDER_IDS = new Set<ProviderId>(["openai", "anthropic", "google", "openrouter", "custom"]);
const MODEL_SOURCES = new Set<CatalogModel["source"]>(["models.dev", "built-in", "custom"]);
const REASONING_LEVELS = new Set<ReasoningLevel>(["off", "minimal", "low", "medium", "high", "xhigh"]);
const REASONING_ORDER: readonly ReasoningLevel[] = ["off", "minimal", "low", "medium", "high", "xhigh"];

const TRANSPORT_INCOMPATIBLE_ID_PATTERNS: Readonly<Record<ModelsDevProviderId, readonly RegExp[]>> = {
  openai: [/embedding/i, /realtime/i, /transcri/i, /whisper/i, /\btts\b/i, /moderation/i, /image/i, /audio/i],
  anthropic: [],
  google: [/embedding/i, /(?:^|[-/])live(?:[-/]|$)/i, /image/i, /lyria/i, /robotics/i, /deep-research/i],
  openrouter: [/embedding/i, /realtime/i, /transcri/i, /whisper/i, /(?:^|[-/])tts(?:[-/]|$)/i, /moderation/i, /image/i, /audio/i],
};

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function finiteNonNegative(value: unknown): number {
  return typeof value === "number" && Number.isFinite(value) && value >= 0 ? value : 0;
}

function stringArray(value: unknown): string[] {
  return Array.isArray(value) ? value.filter((entry): entry is string => typeof entry === "string") : [];
}

function catalogKey(provider: ProviderId, modelId: string): string {
  return `${provider}::${modelId}`;
}

function normalizeReasoningLevel(value: unknown): ReasoningLevel | null {
  if (value === "none") return "off";
  if (value === "max") return "xhigh";
  return REASONING_LEVELS.has(value as ReasoningLevel) ? value as ReasoningLevel : null;
}

function reasoningLevelsForModel(model: Record<string, unknown>): ReasoningLevel[] {
  if (model.reasoning !== true) return [];
  const options = Array.isArray(model.reasoning_options) ? model.reasoning_options : [];
  const effort = options.find((option) => isRecord(option) && option.type === "effort");
  const advertised = isRecord(effort) && Array.isArray(effort.values)
    ? effort.values.map(normalizeReasoningLevel).filter((level): level is ReasoningLevel => level !== null)
    : [];
  const levels = new Set<ReasoningLevel>(["off", ...advertised]);

  // Budget-only models expose a numeric floor instead of named effort tiers.
  // Mobile maps the shared ladder to provider-specific token budgets, so all
  // named controls are usable for that shape.
  if (advertised.length === 0 && options.some((option) => isRecord(option) && option.type === "budget_tokens")) {
    REASONING_ORDER.forEach((level) => levels.add(level));
  }
  // Older cached/public records may only carry `reasoning: true`. Retain the
  // safe shared ladder rather than hiding a capability the provider supports.
  if (levels.size === 1) REASONING_ORDER.forEach((level) => levels.add(level));
  return REASONING_ORDER.filter((level) => levels.has(level));
}

export function isCatalogModel(value: unknown): value is CatalogModel {
  if (!isRecord(value) || !PROVIDER_IDS.has(value.provider as ProviderId)) return false;
  const provider = value.provider as ProviderId;
  return typeof value.id === "string"
    && value.id.length > 0
    && value.key === catalogKey(provider, value.id)
    && typeof value.providerLabel === "string"
    && typeof value.name === "string"
    && typeof value.description === "string"
    && typeof value.reasoning === "boolean"
    && Array.isArray(value.reasoningLevels)
    && value.reasoningLevels.every((level) => REASONING_LEVELS.has(level as ReasoningLevel))
    && typeof value.temperature === "boolean"
    && typeof value.vision === "boolean"
    && typeof value.contextWindow === "number"
    && Number.isFinite(value.contextWindow)
    && value.contextWindow >= 0
    && typeof value.maxOutputTokens === "number"
    && Number.isFinite(value.maxOutputTokens)
    && value.maxOutputTokens >= 0
    && value.transport === NATIVE_PROVIDER_TRANSPORT[provider]
    && MODEL_SOURCES.has(value.source as CatalogModel["source"]);
}

export function isNativeTransportCompatible(provider: ModelsDevProviderId, modelId: string): boolean {
  return !TRANSPORT_INCOMPATIBLE_ID_PATTERNS[provider].some((pattern) => pattern.test(modelId));
}

/**
 * Validate and normalize the public models.dev provider catalog. Only models
 * that the native chat transports can actually call are exposed.
 */
export function parseModelsDevCatalog(payload: unknown): CatalogModel[] {
  if (!isRecord(payload)) throw new Error("models.dev returned an invalid catalog.");
  const models: CatalogModel[] = [];

  for (const [providerKey, providerValue] of Object.entries(payload)) {
    if (!MODELS_DEV_PROVIDERS.has(providerKey as ModelsDevProviderId) || !isRecord(providerValue)) continue;
    const provider = providerKey as ModelsDevProviderId;
    const providerLabel = typeof providerValue.name === "string"
      ? providerValue.name
      : providerDefinition(provider).label;
    if (!isRecord(providerValue.models)) continue;

    for (const [recordKey, modelValue] of Object.entries(providerValue.models)) {
      if (!isRecord(modelValue)) continue;
      const id = typeof modelValue.id === "string" && modelValue.id.trim() ? modelValue.id.trim() : recordKey.trim();
      if (!id) continue;
      const modalities = isRecord(modelValue.modalities) ? modelValue.modalities : {};
      const inputs = stringArray(modalities.input);
      const outputs = stringArray(modalities.output);
      const limits = isRecord(modelValue.limit) ? modelValue.limit : {};
      const contextWindow = finiteNonNegative(limits.context);

      // Image, speech, embedding, and other non-chat entries share the public
      // catalog. The mobile Tutor can only use models that produce text.
      if (!outputs.includes("text") || contextWindow <= 0 || !isNativeTransportCompatible(provider, id)) continue;

      models.push({
        key: catalogKey(provider, id),
        provider,
        providerLabel,
        id,
        name: typeof modelValue.name === "string" && modelValue.name.trim() ? modelValue.name.trim() : id,
        description: typeof modelValue.description === "string" ? modelValue.description.trim() : "",
        reasoning: modelValue.reasoning === true,
        reasoningLevels: reasoningLevelsForModel(modelValue),
        temperature: modelValue.temperature === true,
        vision: inputs.includes("image"),
        contextWindow,
        maxOutputTokens: finiteNonNegative(limits.output),
        transport: NATIVE_PROVIDER_TRANSPORT[provider],
        source: "models.dev",
      });
    }
  }

  if (models.length === 0) throw new Error("models.dev returned no compatible chat models.");
  return dedupeModels(models).sort(compareModels);
}

export function modelHasCapabilities(
  model: CatalogModel,
  capabilities: readonly ModelCapabilityFilter[],
): boolean {
  return capabilities.every((capability) => {
    if (capability === "thinking") return model.reasoning;
    if (capability === "vision") return model.vision;
    return model.contextWindow >= LONG_CONTEXT_THRESHOLD;
  });
}

export function filterCatalogModels(
  models: readonly CatalogModel[],
  query: string,
  providers: readonly ProviderId[],
  capabilities: readonly ModelCapabilityFilter[],
): CatalogModel[] {
  const normalized = query.trim().toLowerCase();
  return models.filter((model) => {
    if (providers.length > 0 && !providers.includes(model.provider)) return false;
    if (!modelHasCapabilities(model, capabilities)) return false;
    if (!normalized) return true;
    return `${model.name} ${model.id} ${model.provider} ${model.providerLabel}`.toLowerCase().includes(normalized);
  });
}

export function catalogSections(
  models: readonly CatalogModel[],
  recentKeys: readonly string[],
  includeRecents: boolean,
): CatalogSections {
  const recentSet = new Set(includeRecents ? recentKeys : []);
  return {
    recent: models.filter((model) => recentSet.has(model.key)),
    cloud: models.filter((model) => model.source !== "custom" && !recentSet.has(model.key)),
    custom: models.filter((model) => model.source === "custom" && !recentSet.has(model.key)),
  };
}

export function customCatalogModel(settings: ProviderSettings): CatalogModel | null {
  if (settings.provider !== "custom" || !settings.model.trim()) return null;
  return {
    key: catalogKey("custom", settings.model.trim()),
    provider: "custom",
    providerLabel: "Custom",
    id: settings.model.trim(),
    name: settings.model.trim(),
    description: settings.baseUrl,
    reasoning: false,
    reasoningLevels: [],
    temperature: true,
    vision: false,
    contextWindow: 0,
    maxOutputTokens: 0,
    transport: NATIVE_PROVIDER_TRANSPORT.custom,
    source: "custom",
  };
}

/**
 * Whether the currently selected model advertises a thinking budget. Providers
 * reject reasoning parameters on models that do not support them, so the
 * thinking control is only offered — and only sent — when this is true.
 */
export function modelSupportsReasoning(
  models: readonly CatalogModel[],
  settings: ProviderSettings,
): boolean {
  const key = catalogKey(settings.provider, settings.model.trim());
  return models.some((model) => model.key === key && model.reasoning);
}

export function modelReasoningLevels(
  models: readonly CatalogModel[],
  settings: ProviderSettings,
): readonly ReasoningLevel[] {
  const key = catalogKey(settings.provider, settings.model.trim());
  return models.find((model) => model.key === key)?.reasoningLevels ?? [];
}

export function resolveModelReasoningLevel(
  models: readonly CatalogModel[],
  settings: ProviderSettings,
  requested: ReasoningLevel,
): ReasoningLevel {
  const available = modelReasoningLevels(models, settings);
  if (available.includes(requested)) return requested;
  if (available.length === 0) return "off";
  if (requested === "off") return available.includes("off") ? "off" : available[0] ?? "off";
  const reasoningOnly = available.filter((level) => level !== "off");
  const requestedIndex = REASONING_ORDER.indexOf(requested);
  const below = [...reasoningOnly]
    .filter((level) => REASONING_ORDER.indexOf(level) <= requestedIndex)
    .at(-1);
  return below ?? reasoningOnly[0] ?? "off";
}

export function modelSupportsTemperature(
  models: readonly CatalogModel[],
  settings: ProviderSettings,
): boolean {
  const key = catalogKey(settings.provider, settings.model.trim());
  return models.find((model) => model.key === key)?.temperature ?? settings.provider !== "openai";
}

export function selectedProviderSettings(current: ProviderSettings, model: CatalogModel): ProviderSettings {
  return {
    provider: model.provider,
    model: model.id,
    baseUrl: model.provider === "custom" ? current.baseUrl : providerDefinition(model.provider).defaultBaseUrl,
    temperature: current.temperature,
  };
}

export function mergeCatalogModels(...groups: ReadonlyArray<readonly CatalogModel[]>): CatalogModel[] {
  return dedupeModels(groups.flat()).sort(compareModels);
}

function dedupeModels(models: readonly CatalogModel[]): CatalogModel[] {
  return Array.from(new Map(models.map((model) => [model.key, model])).values());
}

function compareModels(left: CatalogModel, right: CatalogModel): number {
  return left.providerLabel.localeCompare(right.providerLabel) || left.name.localeCompare(right.name);
}

