	{ value: "tts-1", label: "tts-1 (fast)" },
	{ value: "tts-1-hd", label: "tts-1 HD (higher quality)" },
];

const LEGACY_TTS_VOICES = new Set([
	"alloy",
	"ash",
	"coral",
	"echo",
	"fable",
	"onyx",
	"nova",
	"sage",
