describe("models.dev mobile catalog", () => {
  test("validates the public payload and exposes only callable chat transports", () => {
    const models = parseModelsDevCatalog(payload);
    expect(models).toHaveLength(1);
    expect(models[0]).toMatchObject({
      key: "openai::gpt-chat",
      provider: "openai",
      providerLabel: "OpenAI",
      reasoning: true,
      reasoningLevels: ["off", "low", "high", "xhigh"],
      temperature: false,
      vision: true,
      contextWindow: LONG_CONTEXT_THRESHOLD,
      transport: "openai-responses",
      source: "models.dev",
    });
  });

  test("preserves exact per-model controls and clamps a stored tier", () => {
    const models = parseModelsDevCatalog(payload);
    const settings: ProviderSettings = {
      provider: "openai",
      model: "gpt-chat",
      baseUrl: "https://api.openai.com/v1",
      temperature: 0.6,
    };
    expect(modelReasoningLevels(models, settings)).toEqual(["off", "low", "high", "xhigh"]);
    expect(resolveModelReasoningLevel(models, settings, "minimal")).toBe("low");
    expect(resolveModelReasoningLevel(models, settings, "medium")).toBe("low");
    expect(resolveModelReasoningLevel(models, settings, "xhigh")).toBe("xhigh");
    expect(modelSupportsTemperature(models, settings)).toBe(false);
  });

  test("rejects malformed or chat-empty catalogs instead of showing a false success", () => {
    expect(() => parseModelsDevCatalog(null)).toThrow("invalid catalog");
    expect(() => parseModelsDevCatalog({ openai: { models: {} } })).toThrow("no compatible chat models");
  });

  test("uses an explicit native transport gate for specialized non-chat endpoints", () => {
    expect(NATIVE_PROVIDER_TRANSPORT).toEqual({
      openai: "openai-responses",
      anthropic: "anthropic-messages",
      google: "google-generative-ai",
      openrouter: "openai-chat-completions",
      custom: "openai-chat-completions",
    });
    expect(isNativeTransportCompatible("openai", "gpt-5.6-luna")).toBe(true);
    expect(isNativeTransportCompatible("openai", "gpt-realtime-2.1")).toBe(false);
    expect(isNativeTransportCompatible("openai", "text-embedding-3-small")).toBe(false);
    expect(isNativeTransportCompatible("google", "gemini-3.5-flash")).toBe(true);
    expect(isNativeTransportCompatible("google", "gemini-3.5-live-translate-preview")).toBe(false);
    expect(isNativeTransportCompatible("openrouter", "openai/gpt-image-2")).toBe(false);
  });

  test("rejects poisoned cache records and transport/provider mismatches", () => {
    const valid = parseModelsDevCatalog(payload)[0]!;
    expect(isCatalogModel(valid)).toBe(true);
    expect(isCatalogModel({ ...valid, provider: "untrusted" })).toBe(false);
    expect(isCatalogModel({ ...valid, transport: "openai-chat-completions" })).toBe(false);
    expect(isCatalogModel({ ...valid, key: "openai::different" })).toBe(false);
    expect(isCatalogModel({ ...valid, contextWindow: Number.NaN })).toBe(false);
  });

  test("matches web search, provider, and all-selected-capability semantics", () => {
    const models = parseModelsDevCatalog(payload);
    expect(filterCatalogModels(models, "openai", [], [])).toHaveLength(1);
    expect(filterCatalogModels(models, "gpt-chat", [], [])).toHaveLength(1);
    expect(filterCatalogModels(models, "missing", [], [])).toHaveLength(0);
    expect(filterCatalogModels(models, "", ["anthropic"], [])).toHaveLength(0);
    expect(filterCatalogModels(models, "", [], ["thinking", "vision", "long-context"])).toHaveLength(1);
  });

  test("promotes up to the selected recent keys only when search is empty", () => {
    const models = parseModelsDevCatalog(payload);
    expect(catalogSections(models, [models[0]!.key], true).recent).toEqual(models);
    expect(catalogSections(models, [models[0]!.key], false).recent).toEqual([]);
  });

  test("builds an atomic provider/model/base URL change while preserving temperature", () => {
    const current: ProviderSettings = {
      provider: "openai",
      model: "old",
      baseUrl: "https://api.openai.com/v1",
      temperature: 0.42,
    };
    const model = parseModelsDevCatalog({
      google: {
        name: "Google",
        models: {
          gemini: {
            id: "gemini",
            modalities: { input: ["text"], output: ["text"] },
            limit: { context: 1_000_000, output: 64_000 },
          },
        },
      },
    })[0]!;
    expect(selectedProviderSettings(current, model)).toEqual({
      provider: "google",
      model: "gemini",
      baseUrl: "https://generativelanguage.googleapis.com/v1beta",
      temperature: 0.42,
    });
  });
});
import { describe, expect, test } from "bun:test";
import {
	describeLiveModel,
	findLiveModel,
	isLiveProviderId,
	LIVE_MODELS,
	liveModelsFor,
	nextBestLiveModel,
	recommendedLiveModel,
} from "../keating/live-models";

describe("live model catalog", () => {
	test("every provider offers exactly one recommendation", () => {
		for (const providerId of ["gemini-live", "openai-realtime"] as const) {
			const recommended = liveModelsFor(providerId).filter((model) => model.grade === "recommended");
			expect(recommended).toHaveLength(1);
		}
	});

	test("the recommendation is the first entry, so the fallback chain starts at the best model", () => {
		for (const providerId of ["gemini-live", "openai-realtime"] as const) {
			expect(liveModelsFor(providerId)[0]).toBe(recommendedLiveModel(providerId)!);
		}
	});

	test("model ids are unique", () => {
		const ids = LIVE_MODELS.map((model) => `${model.providerId}/${model.value}`);
		expect(new Set(ids).size).toBe(ids.length);
	});

	test("only legacy models are allowed to lack vision", () => {
		for (const model of LIVE_MODELS) {
			if (model.video === "none") expect(model.grade).toBe("legacy");
		}
	});

	test("a model without vision explains itself, since the camera button goes dead", () => {
		for (const model of LIVE_MODELS) {
			if (model.video === "none") expect(model.note).toBeTruthy();
		}
	});

	test("gemini gets the native video lane and openai the sampled one", () => {
		for (const model of liveModelsFor("gemini-live")) expect(model.video).toBe("native");
		for (const model of liveModelsFor("openai-realtime")) expect(model.video).not.toBe("native");
	});
});

describe("fallback selection", () => {
	test("skips the model that just failed", () => {
		const failing = recommendedLiveModel("gemini-live")!;
		const next = nextBestLiveModel("gemini-live", failing.value);
		expect(next?.value).not.toBe(failing.value);
		expect(next?.providerId).toBe("gemini-live");
	});

	test("walks down the chain rather than re-offering an exhausted model", () => {
		const models = liveModelsFor("openai-realtime");
		const tried: string[] = [];
		let failing = models[0].value;
		for (let step = 1; step < models.length; step += 1) {
			const next = nextBestLiveModel("openai-realtime", failing, tried);
			expect(next).toBeDefined();
			expect(tried).not.toContain(next!.value);
			tried.push(failing);
			failing = next!.value;
		}
		// Everything has now been tried once, so there is nothing left to offer.
		expect(nextBestLiveModel("openai-realtime", failing, tried)).toBeUndefined();
	});

	test("never crosses providers — a Gemini failure cannot fall back to OpenAI", () => {
		const next = nextBestLiveModel("gemini-live", "gemini-3.1-flash-live-preview");
		expect(next?.providerId).toBe("gemini-live");
	});
});

describe("unknown models", () => {
	test("a hand-typed model id is described rather than dropped", () => {
		const described = describeLiveModel("gemini-live", "gemini-99-experimental");
		expect(described.value).toBe("gemini-99-experimental");
		expect(described.label).toBe("gemini-99-experimental");
		expect(described.note).toContain("tested list");
	});

	test("a known model keeps its catalog entry", () => {
		const known = recommendedLiveModel("openai-realtime")!;
		expect(describeLiveModel("openai-realtime", known.value)).toBe(known);
	});

	test("lookups do not match across providers", () => {
		expect(findLiveModel("openai-realtime", "gemini-3.1-flash-live-preview")).toBeUndefined();
	});

	test("provider ids are recognised", () => {
		expect(isLiveProviderId("gemini-live")).toBe(true);
		expect(isLiveProviderId("openai-tts")).toBe(false);
	});
});
